// browser_take_screenshot 实现：CDP Page.captureScreenshot 取 base64，落盘由主程序负责
#include "browser_take_screenshot.h" // 自身声明
#include "server/cdp_client.h" // CdpClient::Screenshot
#include "browser_tool/tool_helpers.h" // 回包工具
#include "utils/js_builder.h" // js::SafeRef/Element
#include "utils/json_util.h" // JSON 工具
namespace {
void ReplyImage(int id, const std::string& format, bool ok, CefRefPtr<CefDictionaryValue> result, const std::string& error, const std::string& hint) { if (!ok || result == nullptr) { tool::ReplyError(id, error.empty() ? hint : error); return; } CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetString("base64", StrOf(result, "data")); data->SetString("format", format); tool::Reply(id, data); } // 截图结果统一回 {base64,format}
}
void BrowserTakeScreenshotTool::Run(const ToolRequest& req) { std::string format = "png"; ArgGetString(req.args, "type", format); bool full_page = false; ArgGetBool(req.args, "fullPage", full_page); std::string ref; ArgGetString(req.args, "ref", ref); const int id = req.id; CefRefPtr<CdpClient> cdp = req.cdp; if (js::SafeRef(ref).empty()) { cdp->Screenshot(format, full_page, nullptr, [id, format](bool ok, CefRefPtr<CefDictionaryValue> result, const std::string& error) { ReplyImage(id, format, ok, result, error, "截图失败"); }); return; } cdp->Evaluate(js::Element(ref, "var r=el.getBoundingClientRect();return {x:r.left,y:r.top,w:r.width,h:r.height};"), false, [id, format, cdp](bool ok, CefRefPtr<CefValue> value, const std::string& error) { if (!ok || value == nullptr || value->GetType() != VTYPE_DICTIONARY) { tool::ReplyError(id, error.empty() ? "元素定位失败" : error); return; } CefRefPtr<CefDictionaryValue> box = value->GetDictionary(); double x = 0, y = 0, w = 0, h = 0; ArgGetDouble(box, "x", x); ArgGetDouble(box, "y", y); ArgGetDouble(box, "w", w); ArgGetDouble(box, "h", h); CefRefPtr<CefDictionaryValue> clip = MakeDict(); clip->SetDouble("x", x); clip->SetDouble("y", y); clip->SetDouble("width", w); clip->SetDouble("height", h); clip->SetDouble("scale", 1.0); cdp->Screenshot(format, false, clip, [id, format](bool ok2, CefRefPtr<CefDictionaryValue> result2, const std::string& error2) { ReplyImage(id, format, ok2, result2, error2, "元素截图失败"); }); }); } // 元素截图：先取盒子再按视口坐标裁剪（clip 截图）
